import hashlib
from pathlib import Path

ROOT = Path(__file__).parents[1]
EXCLUDED_DIRS = {'.git', '.idea', '.venv', '.pytest_cache', '__pycache__', 'backups', 'data',
                 # Local assistant memory. Excluded here as well as in .gitignore: the
                 # manifest is generated by walking the filesystem, so it does not consult
                 # .gitignore. Without this the published manifest lists files that are not
                 # in the repository, and every verification of it fails.
                 '.workbuddy-ai'}
EXCLUDED_SUFFIXES = {'.pyc', '.pyo', '.db', '.log'}
EXCLUDED_FILES = {'.env', 'MANIFEST.txt', 'SHA256SUMS.txt'}


def included_files():
    for path in ROOT.rglob('*'):
        if not path.is_file():
            continue
        relative = path.relative_to(ROOT)
        if any(part in EXCLUDED_DIRS for part in relative.parts):
            continue
        if path.name in EXCLUDED_FILES or path.suffix in EXCLUDED_SUFFIXES:
            continue
        if path.name.endswith('.bound.openapi.yaml') or path.name.endswith('.bound.dify.yml'):
            continue
        if relative.as_posix() == 'evaluation/latest_report.json':
            continue
        yield path, relative.as_posix()


def main():
    files = sorted(included_files(), key=lambda item: item[1])
    manifest = ['Dify Production Support Platform release manifest', f'files: {len(files)}', '']
    sums = []
    for path, relative in files:
        manifest.append(relative)
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        sums.append(f'{digest}  ./{relative}')
    (ROOT / 'MANIFEST.txt').write_text('\n'.join(manifest) + '\n', encoding='utf-8')
    (ROOT / 'SHA256SUMS.txt').write_text('\n'.join(sums) + '\n', encoding='utf-8')
    print(f'Wrote MANIFEST.txt and SHA256SUMS.txt for {len(files)} files')


if __name__ == '__main__':
    main()
